-- Style damage, restored from the public Dawn of Light database.
--
-- A Mauler's Wild Swing did no damage. Nor did any other Mauler style, nor any
-- style belonging to a class this conversion reopened: every one of the 542
-- rows added by 88-combat-styles.sql went in with GrowthRate 0.
--
-- GrowthRate is the style's damage. Zero means the swing lands and the style
-- adds nothing on top, which is what "0 + 0" on the screen was saying.
--
-- The loss was a transcription slip, not missing data. Everything else in
-- those rows came across correctly -- endurance cost, opening requirements,
-- weapon type, the to-hit and defence bonuses -- and only this one column was
-- written as zero throughout. Wild Swing is 0.04 in the source, at the same
-- ID and ClassId we already store.
--
-- The values are the public database's own -- github.com/Eve-of-Darkness/
-- db-public, data/Style.json -- matched on ID and ClassId, which is how styles
-- are identified everywhere else in the code. That database is where these
-- styles came from in the first place: it carries 48 Fist Wraps and 48 Mauler
-- Staff styles, of which only three per line are genuinely zero, topping out
-- at 0.97 and 0.98.
--
-- Twenty-five styles appear under more than one line -- Tenacity sits in
-- Champion Abilities and in three archetype lines -- and every one of them
-- agrees with itself on damage, so keeping one row per ID and ClassId loses
-- nothing.
--
-- Three guards make this safe to run against any database:
--
--   Only rows sitting at zero are changed, so a style that already has a
--   value keeps it and nothing stock is touched.
--
--   Only values the public database gives as greater than zero are listed, so
--   styles meant to be zero stay zero -- the whole Battlemaster line, and
--   three in each Mauler line.
--
--   Matching is on ID and ClassId together, never on name, so two classes
--   sharing a style name cannot bleed into each other.
--
-- Re-running changes nothing: after the first pass no row is still at zero.

CREATE TEMPORARY TABLE IF NOT EXISTS gaheris_style_growth (
    ID INT NOT NULL,
    ClassId INT NOT NULL,
    GrowthRate DOUBLE NOT NULL,
    PRIMARY KEY (ID, ClassId)
);

TRUNCATE TABLE gaheris_style_growth;


UPDATE style s
  JOIN gaheris_style_growth g
    ON g.ID = s.ID AND g.ClassId = s.ClassId
   SET s.GrowthRate = g.GrowthRate
 WHERE s.GrowthRate = 0;

DROP TEMPORARY TABLE gaheris_style_growth;
